// Staff console shell baselines (#309): 1280 and 768, light and dark. The console is desktop-first
// but usable at 360: no horizontal scroll and every nav item reachable. Baselines live in
// e2e/__screenshots__ and are only generated by the e2e workflow's `update_snapshots` dispatch.
import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';

test('admin console shell', { tag: '@visual' }, async ({ adminAs }, testInfo) => {
  test.skip(testInfo.project.name.includes('-360-'), 'baselines at 1280 and 768 only');
  const baseline = testInfo.snapshotPath('admin-console.png', { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
  const page = await adminAs('staff');
  await page.goto('/flags');
  await expect(page.getByRole('heading', { level: 1, name: 'Flags' })).toBeVisible();
  await expect(page).toHaveScreenshot('admin-console.png', {
    fullPage: true,
    // The signed-in email differs per run only if fixtures change; mask it anyway.
    mask: [page.getByTestId('staff-strip').locator('span').last()],
  });
});

test('admin console is usable at 360', async ({ adminAs }, testInfo) => {
  test.skip(!testInfo.project.name.includes('-360-'), '360 px projects only');
  const page = await adminAs('staff');
  await page.goto('/');
  const overflow = await page.evaluate(
    () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
  );
  expect(overflow).toBeLessThanOrEqual(0);
  const links = page.getByRole('navigation', { name: 'Console' }).getByRole('link');
  await expect(links).toHaveCount(6);
  await links.filter({ hasText: 'Flags' }).click();
  await expect(page.getByRole('heading', { level: 1, name: 'Flags' })).toBeVisible();
});
